import {winnerCard} from './winners.js';
import {preparePhoto} from './photo-crop.js';
import {uploadPhoto,newRecordID} from './media-rules.js';
import {editorStyles} from './visual-editor.js';
export async function openWinners({sb,api,host,editor,status,config,isCurrent}){
 editorStyles();if(!document.querySelector('[data-winner-styles]')){const link=document.createElement('link');link.rel='stylesheet';link.href='/assets/winners.css';link.dataset.winnerStyles='';document.head.append(link);}
 editor.replaceChildren();let rows=[],dirty=false,busy=false,blob=null,active=true,photoVersion=0;
 const before=e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}};
 const leave=e=>{if(busy||(dirty&&!confirm('Discard unsaved winner changes?'))){e.preventDefault();return;}active=false;photoVersion++;if(blob)URL.revokeObjectURL(blob);document.removeEventListener('elan:admin-leave',leave);window.removeEventListener('beforeunload',before);};
 document.addEventListener('elan:admin-leave',leave);window.addEventListener('beforeunload',before);
 function clear(){dirty=false;photoVersion++;editor.replaceChildren();if(blob)URL.revokeObjectURL(blob);blob=null;}
 async function list(){let loaded=[];for(let offset=0;;offset+=100){const r=await sb.from('elan_winners').select('*').order('sort_order').order('id').range(offset,offset+99);if(r.error)throw r.error;loaded.push(...r.data);if(r.data.length<100)break;}if(!active||!isCurrent())return;rows=loaded;host.innerHTML='<section class="app-card"><p class="app-badge">FIRST EDITION / WINNERS & AWARDS</p><h2>The people behind the awards.</h2><p>Add an individual profile or one shared team entry. Reflections are optional. Only published entries appear on the winners page.</p><div class="app-actions"><button data-add>Add a winner or team</button><a href="/winners-2026.html" target="_blank" rel="noopener">View winners page ↗</a></div><div class="collection-grid" data-list></div></section>';host.querySelector('[data-add]').onclick=()=>edit();const grid=host.querySelector('[data-list]');for(const row of rows){const card=document.createElement('article');card.className='collection-card';const h=document.createElement('h3');h.textContent=row.name;const p=document.createElement('p');p.textContent=row.award+' · '+row.competition;const state=document.createElement('p');state.textContent=(row.published?'Published':'Draft')+' · Order '+row.sort_order;const b=document.createElement('button');b.textContent='Edit winner';b.onclick=()=>edit(row);card.append(h,p,state,b);grid.append(card);}if(!rows.length)grid.textContent='No winners added yet. Start with an individual or a team.';}
 function edit(original){if(busy||(dirty&&!confirm('Discard unsaved changes?')))return;clear();const row=original||{id:newRecordID(),edition_slug:'2026',competition:'Crisis Command',sort_order:Math.min(10000,Math.max(0,...rows.map(r=>r.sort_order))+1),approved:false,published:false,image_url:''};let photo=null,uploaded=null;
 editor.innerHTML='<section class="app-card"><h2>'+ (original?'Edit winner':'Add winner or team')+'</h2><div class="collection-edit"><form class="collection-form"><label>Competition<select name="competition"><option>Crisis Command</option><option>Cent$ible</option><option>Other honours</option></select></label><label>Exact award name<input name="award" maxlength="160" required placeholder="Use the award as it was announced"></label><label>Winner’s name or team name<input name="name" maxlength="200" required></label><label>Team members (optional)<textarea name="members" maxlength="2000" rows="3" placeholder="One member per line. Leave blank for an individual."></textarea></label><label>School or institution (optional)<input name="school" maxlength="300"></label><label>Short introduction (optional)<textarea name="introduction" maxlength="600" rows="3" placeholder="A sentence about the person or team."></textarea></label><label>In their words (optional)<textarea name="reflection" maxlength="2000" rows="7" placeholder="Their own memory of Élan and what the award meant to them."></textarea></label><label>Portrait or team photograph (optional)<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><p>Choose the crop after selecting a photo. JPEG, PNG or WebP, up to 8 MB.</p><button type="button" data-remove-photo class="secondary">Remove photograph from this entry</button><label>Display order<input name="sort_order" type="number" min="0" max="10000" required></label><p>Lower numbers appear first within each competition.</p><label class="check-row"><input name="approved" type="checkbox">I have permission to publish these names, words and photograph.</label><label class="check-row"><input name="published" type="checkbox">Show on the website</label><div class="app-actions"><button type="submit">Save winner</button><button type="button" data-cancel class="secondary">Cancel</button></div></form><aside><p class="app-badge">PROFILE PREVIEW</p><div class="winner-admin-preview"></div></aside></div></section>';
 const form=editor.querySelector('form'),f=form.elements,previewHost=editor.querySelector('.winner-admin-preview');let imageURL=row.image_url||'';
 for(const key of ['competition','award','name','members','school','introduction','reflection','sort_order'])f.namedItem(key).value=row[key]??'';for(const key of ['approved','published'])f.namedItem(key).checked=!!row[key];
 function values(){const v={id:row.id,edition_slug:'2026',image_url:imageURL};for(const key of ['competition','award','name','members','school','introduction','reflection'])v[key]=f.namedItem(key).value.trim();v.sort_order=Number(f.namedItem('sort_order').value);v.approved=f.namedItem('approved').checked;v.published=f.namedItem('published').checked;return v;}
 function preview(){const v=values();if(blob)v.image_url='/assets/preview';const card=winnerCard(v,config.supabaseUrl);if(blob)card.querySelector('img').src=blob;previewHost.replaceChildren(card);}
 form.oninput=()=>{dirty=true;preview();};f.namedItem('photo').onchange=async()=>{const file=f.namedItem('photo').files[0];if(!file)return;const version=++photoVersion;busy=true;try{const cropped=await preparePhoto(file);if(!active||version!==photoVersion)return;if(!cropped){f.namedItem('photo').value='';return;}photo=cropped;uploaded=null;if(blob)URL.revokeObjectURL(blob);blob=URL.createObjectURL(photo);dirty=true;preview();}catch(e){status(e.message,true);}finally{busy=false;}};
 editor.querySelector('[data-remove-photo]').onclick=()=>{if(busy)return;photoVersion++;photo=null;uploaded=null;imageURL='';f.namedItem('photo').value='';if(blob)URL.revokeObjectURL(blob);blob=null;dirty=true;preview();};editor.querySelector('[data-cancel]').onclick=()=>{if(!busy&&(!dirty||confirm('Discard unsaved changes?')))clear();};
 if(original){const remove=document.createElement('button');remove.type='button';remove.className='secondary';remove.textContent='Delete this winner';form.append(remove);remove.onclick=async()=>{if(busy||!confirm('Remove '+row.name+' from the winners page? This removes this entry, not the stored photo.'))return;busy=true;form.inert=true;try{const r=await sb.from('elan_winners').delete().eq('id',row.id).select('id').single();if(r.error)throw r.error;if(r.data?.id!==row.id)throw Error('Deletion was not confirmed.');clear();await list();status('Winner removed.');}catch(e){status(e.message,true);}finally{busy=false;form.inert=false;}};}
 form.onsubmit=async e=>{e.preventDefault();if(busy||!form.reportValidity())return;const v=values();if(!v.award||!v.name){status('Enter the award and winner name.',true);return;}if(v.published&&!v.approved){status('Confirm permission before publishing.',true);return;}busy=true;form.inert=true;status('Saving winner…');try{if(photo){uploaded??=await uploadPhoto(photo,sb,api);v.image_url=uploaded;}const r=await sb.from('elan_winners').upsert(v).select('id,published').single();if(r.error)throw r.error;if(r.data.id!==v.id||r.data.published!==v.published)throw Error('Save was not confirmed.');clear();await list();status(v.published?'Winner published.':'Winner saved as a draft.');}catch(e){status(e.message,true);}finally{busy=false;form.inert=false;}};preview();editor.scrollIntoView({block:'start'});
 }
 await list();status('');
}
